}

.article-card-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  line-height: 1.4;
  color: var(--color-text);
}

.article-card-title a {
  color: inherit;
  text-decoration: none;
}

.article-card-title a:hover {
  color: var(--color-link);
}

.article-card-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.article-card-meta .author-avatar {
