/* OpenLearnHub Styles */

:root {
  --color-primary: #0a0a23;
  --color-accent: #FEAC32;
  --color-link: #002EAD;
  --color-bg: #ffffff;
  --color-bg-alt: #f8f9fa;
  --color-text: #1a1a1a;
  --color-text-muted: #6b7280;
  --color-border: #e5e7eb;
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
}

a {
  color: var(--color-link);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Header */
.header {
  background: var(--color-primary);
  color: white;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent);
  text-decoration: none;
}

.logo:hover {
  text-decoration: none;
}

.search-bar {
  flex: 1;
  max-width: 400px;
  margin: 0 2rem;
}

.search-bar input {
  width: 100%;
  padding: 0.6rem 1rem;
  border: none;
  border-radius: 4px;
  background: rgba(255,255,255,0.1);
  color: white;
  font-size: 0.9rem;
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.6);
}

.search-bar input:focus {
  outline: none;
  background: rgba(255,255,255,0.15);
}

.nav-links {
  display: flex;
  gap: 2rem;
}

.nav-links a {
  color: white;
  text-decoration: none;
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--color-accent);
  text-decoration: none;
}

/* Mobile menu */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  flex-direction: column;
  background: var(--color-primary);
  padding: 1rem 2rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  color: white;
  text-decoration: none;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav a:last-child {
  border-bottom: none;
}

/* Banner */
.banner {
  background: var(--color-accent);
  color: var(--color-primary);
  text-align: center;
  padding: 0.75rem 1rem;
  font-weight: 600;
  font-size: 0.95rem;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

/* Featured Article */
.featured-article {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 3rem;
  background: linear-gradient(135deg, #1a1a3e 0%, #0a0a23 100%);
}

.featured-article img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}

.featured-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 2rem;
  background: linear-gradient(transparent, rgba(10,10,35,0.95));
  color: white;
}

.tag-label {
  display: inline-block;
  padding: 0.3rem 0.8rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.tag-ai { background: #fef3c7; color: #92400e; }
.tag-web-scraping { background: #dbeafe; color: #1e40af; }
.tag-databases { background: #d1fae5; color: #065f46; }
.tag-elasticsearch { background: #ede9fe; color: #5b21b6; }
.tag-data-engineering { background: #fce7f3; color: #9d174d; }
.tag-python { background: #fef3c7; color: #92400e; }
.tag-node-js { background: #d1fae5; color: #065f46; }
.tag-google-sheets { background: #dbeafe; color: #1e40af; }
.tag-ai-automation { background: #ede9fe; color: #5b21b6; }

.featured-content .tag-label {
  background: var(--color-accent);
  color: var(--color-primary);
}

.featured-title {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1rem;
  line-height: 1.3;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  color: var(--color-primary);
}

.author-name {
  font-weight: 500;
}

.timestamp {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
}

/* Section header */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.section-title {
  font-size: 1.75rem;
  font-weight: 700;
}

/* Article Grid */
.article-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 2rem;
  margin-bottom: 2rem;
}

.article-card {
  border: 1px solid var(--color-border);
  border-radius: 12px;
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.2s;
}

.article-card:hover {
  box-shadow: 0 8px 30px rgba(0,0,0,0.1);
  transform: translateY(-2px);
}

.article-card img {
  width: 100%;
  height: 180px;
  object-fit: cover;
}

.article-card-content {
  padding: 1.25rem;
}

.article-card .tag-label {
  margin-bottom: 0.5rem;
}

.article-card-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  line-height: 1.4;
  color: var(--color-text);
}

.article-card-title a {
  color: inherit;
  text-decoration: none;
}

.article-card-title a:hover {
  color: var(--color-link);
}

.article-card-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.article-card-meta .author-avatar {
  width: 28px;
  height: 28px;
  font-size: 0.75rem;
}

