.load-more-container {
  text-align: center;
  margin-top: 3rem;
}

.btn-load-more {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-load-more:hover {
  background: #1a1a3e;
}

.btn-load-more:disabled {
  background: #9ca3af;
  cursor: not-allowed;
}

