.faq-icon {
  font-size: 1.25rem;
  transition: transform 0.3s;
}

.faq-item.open .faq-icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer-content {
  padding: 1.25rem;
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
}

/* Responsive */
@media (max-width: 768px) {
  .header-main {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .search-bar {
    order: 3;
    max-width: 100%;
    width: 100%;
    margin: 0;
  }

  .nav-links {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .featured-title {
    font-size: 1.5rem;
  }

  .featured-article img {
    height: 280px;
  }

  .article-grid {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .amount-tabs {
    flex-wrap: wrap;
  }

  .amount-tab {
    min-width: calc(50% - 0.25rem);
  }
}
